// ============================================================
// DATA HELPERS — now backed by Supabase via DB client (db.js)
// All async functions. Synchronous wrappers kept for
// non-critical helpers that only work with cached data.
// ============================================================

// ---- Init: load data into cache on app start ----
async function initDB() {
  if (!DB.auth.isLoggedIn()) return;
  await Promise.all([
    DB.getCustomers(true),
    DB.getPayments(true)
  ]);
}

// ---- Sync getters (use cache — must call initDB first) ----
function getCustomers() {
  return DB._cache?.customers || [];
}

function getPayments() {
  return DB._cache?.payments || [];
}

// ---- Async getters (always fresh or cached) ----
async function getCustomersAsync(force = false) {
  return DB.getCustomers(force);
}

async function getPaymentsAsync(force = false) {
  return DB.getPayments(force);
}

// ---- Save helpers (async) ----
async function saveCustomer(customerObj) {
  const existing = getCustomers().find(c => c.id === customerObj.id);
  let res;
  if (existing) {
    res = await DB.customers.update(customerObj.id, customerObj);
  } else {
    res = await DB.customers.create(customerObj);
  }
  await DB.getCustomers(true); // refresh cache
  return res;
}

async function deleteCustomer(id) {
  const res = await DB.customers.delete(id);
  await DB.photos.delete(id); // delete photos
  DB.invalidateCustomers();
  DB.invalidatePayments();
  return res;
}

async function savePaymentRecord(paymentObj) {
  const existing = getPayments().find(p => p.id === paymentObj.id);
  let res;
  if (existing) {
    res = await DB.payments.update(paymentObj.id, paymentObj);
  } else {
    res = await DB.payments.create(paymentObj);
  }
  await DB.getPayments(true); // refresh cache
  return res;
}

async function deletePaymentRecord(id) {
  const res = await DB.payments.delete(id);
  await DB.getPayments(true);
  return res;
}

// ---- Sync convenience (cache-only) ----
function getCustomerById(id) {
  return getCustomers().find(c => c.id === id) || null;
}

function getPaymentsByCustomer(customerId) {
  return getPayments()
    .filter(p => p.customerId === customerId)
    .sort((a, b) => new Date(a.tgl) - new Date(b.tgl));
}

// ---- ID generators (async, ask server) ----
async function generateCustomerId() {
  return DB.customers.nextId();
}

async function generatePaymentId() {
  return DB.payments.nextId();
}

// ---- Photo helpers (async) ----
async function getCustomerPhoto(customerId) {
  const photos = await DB.getPhotos(customerId);
  return photos['cust'] || null;
}

async function getItemPhotos(customerId) {
  const photos = await DB.getPhotos(customerId);
  const items = [];
  for (let i = 0; i < 5; i++) {
    const k = `item_${i}`;
    if (photos[k]) items.push(photos[k]);
  }
  // Fallback legacy key
  if (items.length === 0 && photos['item']) items.push(photos['item']);
  return items;
}

async function savePhotosForCustomer(customerId, custPhotoData, itemPhotosArray) {
  const photosObj = {};
  if (custPhotoData) photosObj['cust'] = custPhotoData;
  itemPhotosArray.forEach((url, i) => {
    if (url) photosObj[`item_${i}`] = url;
  });
  if (Object.keys(photosObj).length > 0) {
    await DB.photos.saveAll(customerId, photosObj);
    DB.invalidatePhotos(customerId);
  }
}

async function deletePhotosForCustomer(customerId) {
  await DB.photos.delete(customerId);
  DB.invalidatePhotos(customerId);
}

// ---- WA Log helpers (async) ----
async function waAddLogDB(entry) {
  await DB.walogs.add(entry);
}

async function waGetLogsDB() {
  return DB.walogs.getAll();
}

async function waClearLogsDB() {
  return DB.walogs.clearAll();
}
